  // 布局
  require('../stories/grid');
  // 操作反馈
  require('../stories/feedback');
  // 其他
  require('../stories/other');
}

configureActions({
  depth: 100,
});

addDecorator(
  withInfo({
    header: true,
    maxPropsIntoLine: 100,
    maxPropObjectKeys: 100,
    maxPropArrayLength: 100,
    maxPropStringLength: 100,
  }),
);
addDecorator(withNotes);
addDecorator(
  withOptions({
    name: `${name} v${version}`,
