import { Form, Input } from 'antd';

const Example = () => {
  const [trimValue, setTrimValue] = useTrimInput();
  const [fullTrimValue, setFullTrimValue] = useTrimInput(true);
  return (
    <>
      <input
        value={trimValue}
        onChange={setTrimValue}
        placeholder="请输入姓名"
      />
      <input
        value={fullTrimValue}
        onChange={setFullTrimValue}
        placeholder="请输入姓名"
      />
    </>
  );
};

export default Example;
```

