{
    "short_name": "李金珂的小屋",
    "name": "李金珂的个人网站",
    "icons": [
      {
        "src": "/logos/logo_48.png",
        "type": "image/png",
        "sizes": "48x48"
      },
      {
        "src": "/logos/logo_96.png",
        "type": "image/png",
        "sizes": "96x96"
      },
      {
        "src": "/logos/logo_192.png",
        "type": "image/png",
        "sizes": "192x192"
      },
      {
        "src": "/logos/logo_512.png",
        "type": "image/png",
        "sizes": "512x512"
      }
    ],
    "start_url": "/",
    "display": "standalone",
    "background_color": "#31c27c",
    "theme_color": "#fff"
  }
```

导入

```
  <link rel="manifest" href="manifest.json" crossorigin="use-credentials">
```

