  xmlns="http://www.w3.org/2000/svg"
  width="39"
  height="37"
  viewBox="0 0 39 37"
>
  <g fill="none" fill-rule="evenodd">
    <path d="M0 0L44 0 44 44 0 44z" transform="translate(-4 -3)" />
